diff --git a/lib/src/agent/agent_loop.dart b/lib/src/agent/agent_loop.dart
index aa07573956..d498e12b92 100644
--- a/lib/src/agent/agent_loop.dart
+++ b/lib/src/agent/agent_loop.dart
@@ -2500,7 +2500,7 @@ Future<_ExecutedToolCallOutcome> _executePreparedToolCall(
   // Issue #1786: the foreground budget supervises every call the stuck
   // supervisor's exclusion list does not exempt (human-blocking tools,
   // subagents) — it is the unconditional outer bound, on by default.
-  final budgetApplies = _budgetAppliesTo(toolCall.name);
+  final budgetApplies = _budgetAppliesTo(toolCall.name, stuckTool);
   final execution = supervised || budgetApplies
       ? _superviseToolExecution(
           toolCall: toolCall,
diff --git a/lib/src/agent/agent_loop_foreground_budget.dart b/lib/src/agent/agent_loop_foreground_budget.dart
index 2c50e43e73..3729d95aa1 100644
--- a/lib/src/agent/agent_loop_foreground_budget.dart
+++ b/lib/src/agent/agent_loop_foreground_budget.dart
@@ -122,12 +122,13 @@ final class _BudgetClock {
 }

 /// Whether the budget supervises a tool call: everything EXCEPT the same
-/// human-blocking / self-supervised class the stuck supervisor excludes by
-/// default — `ask`/`request_secret` block on a human by design (a budget
-/// force would abort a deliberation), `task` runs whole subagents whose
-/// own machinery owns long runs.
-bool _budgetAppliesTo(String toolName) =>
-    !StuckToolConfig.defaultStuckExcludedTools.contains(toolName);
+/// human-blocking / self-supervised class the stuck supervisor excludes —
+/// consulted through the SAME effective exclusion list (issue #2271): the
+/// configured [StuckToolConfig.excludeTools] when a stuck config exists,
+/// the static defaults otherwise. One source of truth — no
+/// static-vs-configured divergence between the two gates.
+bool _budgetAppliesTo(String toolName, StuckToolConfig? stuck) =>
+    !(stuck ?? const StuckToolConfig()).excludes(toolName);

 /// Arms the ladder's two timers for one call: the rung-1 offer deadline at
 /// B/2 and the rung-2 force deadline at B. Timers are no-ops once the call
diff --git a/lib/src/agent/agent_loop_stuck_supervision.dart b/lib/src/agent/agent_loop_stuck_supervision.dart
index ba55969110..9b0b8c0b1c 100644
--- a/lib/src/agent/agent_loop_stuck_supervision.dart
+++ b/lib/src/agent/agent_loop_stuck_supervision.dart
@@ -792,19 +792,16 @@ Future<_SupervisedAttempt> _supervisedAttempt({
   void observe(ToolExecutionResult partial) =>
       _observeAttemptOutput(clock, budgetClock, partial);

-  // The executor's token: [REDACTED:Sensitive-Value] RUN token itself unless the stuck stage
-  // machine is armed (it needs a per-call token to cancel-and-RETRY this
-  // call). Issue #1786 review fix: the budget-only path must preserve the
-  // loop's hook/executor identity contract — beforeToolCall and the
-  // executor observe the SAME token instance, and esc cancels the executor
-  // natively. The budget's own escalation rides the YIELD token (bash's
-  // soft hand-back) plus the bounded grace for everything else; it never
-  // needed to swap this token. A run without a token (runAgentLoop(null))
-  // keeps the per-call token so the budget's abort path still has a
-  // cancel handle.
-  final executorToken = stuck == null
-      ? (runToken ?? callSource.token)
-      : callSource.token;
+  // The executor ALWAYS holds the per-call token (issue #2271): the stuck
+  // stage machine needs it to cancel-and-RETRY this call, and the budget
+  // ladder's force escalation signals THIS token (`_escalateBudgetNow`
+  // cancels `attemptCallSource`) — handing the executor the run token
+  // instead left the force swinging at a token nobody held, so a
+  // token-obeying tool ran on as an uncancelled orphan behind a false
+  // "ignored cancellation". Esc / Agent.abort stays native through the
+  // run → call link above: the run token's cancel fires this token with
+  // the run's reason.
+  final executorToken = callSource.token;
   final inner = runZoned<Future<ToolExecutionResult>>(
     () => run(executorToken, observe),
     zoneValues: {yieldTokenZoneKey: yieldSource.token},
diff --git a/test/agent/agent_test.dart b/test/agent/agent_test.dart
index 0d0b694172..1ef10d1bc1 100644
--- a/test/agent/agent_test.dart
+++ b/test/agent/agent_test.dart
@@ -728,7 +728,10 @@ void main() {
         // The blocked result goes back to the model, which answers next turn.
         expect(fake.calls, 2);

-        // A later unblocked run shows the hook receives the run's cancel token.
+        // A later unblocked run shows the hook receives the run's cancel
+        // token while the executor holds the supervisor's linked per-call
+        // token (issue #2271) — distinct instances, one cancellation chain:
+        // aborting the run cancels both.
         seen = null;
         final fake2 = _FakeStreamFunction([
           _toolTurn([_call('call-2', 'weather')]),
@@ -739,6 +742,7 @@ void main() {
           streamFunction: fake2.call,
           toolExecutor: (toolCall, cancelToken, onUpdate) async {
             executorToken = cancelToken;
+            await cancelToken!.onCancel;
             return ToolExecutionResult.text('ok');
           },
           beforeToolCall: (context, cancelToken) {
@@ -747,8 +751,23 @@ void main() {
           },
